import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    # Start the script in a subprocess
    process = subprocess.Popen([script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    # Get the process object for monitoring
    proc = psutil.Process(process.pid)

    cpu_usage = 0.0
    memory_usage = 0.0
    start_time = time.time()

    try:
        while True:
            # Check if process has finished
            if process.poll() is not None:
                break

            # Check if timeout has been reached
            if time.time() - start_time > timeout:
                # Terminate the process if it exceeds timeout
                proc.terminate()
                try:
                    proc.wait(timeout=2)
                except psutil.TimeoutExpired:
                    proc.kill()
                break

            # Get current CPU and memory usage
            try:
                cpu_percent = proc.cpu_percent(interval=0.1)
                memory_info = proc.memory_info()
                memory_rss = memory_info.rss

                # Accumulate CPU usage (in percentage over time)
                cpu_usage += cpu_percent * 0.1  # 0.1 seconds interval

                # Accumulate memory usage (RSS in bytes)
                memory_usage += memory_rss

            except (psutil.NoSuchProcess, psutil.AccessDenied):
                # Process might have terminated or been denied access
                break

            # Small delay to avoid high CPU usage in the loop
            time.sleep(0.05)

    except Exception:
        # Ensure process is terminated in case of unexpected errors
        if process.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=2)
            except psutil.TimeoutExpired:
                proc.kill()

    # Final check for process state
    if process.poll() is None:
        proc.terminate()
        try:
            proc.wait(timeout=2)
        except psutil.TimeoutExpired:
            proc.kill()

    return {
        'CPU Usage': cpu_usage,
        'Memory Usage': memory_usage
    }

